import unittest
from unittest.mock import patch

import pandas as pd

from app.config import load_config
from app.database import fetch_alerts, fetch_market_snapshots
from app.pipeline import (
    MonitorCycleResult,
    _alert_matches_chain_group,
    _build_alert_stage_alignment_line,
    _build_detailed_alert_section_lines,
    _build_detailed_alert_priority_label,
    _build_evening_context,
    _build_market_focus_observation,
    _build_market_focus_snapshot,
    _build_morning_context,
    _build_stage_chain_group_strength_map,
    _build_stage_chain_focus_snapshot,
    _build_stage_focus_confirmation_text,
    _build_stage_focus_observation_suffix,
    _classify_market_focus_state,
    _extract_stock_pool_observation_from_report,
    _format_alert_block,
    _resolve_detailed_alert_field_specs,
    _rank_stage_chain_groups,
    _render_display_fields,
    _resolve_detailed_alert_display_variant,
    _resolve_task_result_summary_case,
    _sort_alerts_for_detailed_view,
    build_cycle_console_output,
    build_cycle_console_output_with_strategy,
    run_monitor_cycle,
)


class MonitorPipelineTests(unittest.TestCase):
    """Verify the core monitor cycle stays reusable and persistent."""

    def test_run_monitor_cycle_returns_persisted_result(self) -> None:
        temp_dir = Path(tempfile.mkdtemp())
        database_path = temp_dir / "monitor.db"
        snapshot_path = temp_dir / "stock_pool_health_snapshot.json"
        try:
            with (
                patch.dict(
                    "os.environ",
                    {
                        "MONITOR_DATABASE_PATH": str(database_path),
                        "MONITOR_STOCK_POOL_HEALTH_SNAPSHOT_PATH": str(snapshot_path),
                    },
                    clear=False,
                ),
                patch("app.pipeline.fetch_realtime_quotes", return_value=pd.DataFrame()),
            ):
                config = load_config()
                result = run_monitor_cycle(config)

            snapshots = fetch_market_snapshots(database_path)
            alerts = fetch_alerts(database_path)

            self.assertEqual("demo-fallback", result.quote_source)
            self.assertGreaterEqual(len(result.market_rows), 6)
            self.assertEqual(len(result.market_rows), len(snapshots))
            self.assertEqual(len(result.alerts), len(alerts))
            self.assertTrue(result.morning_report)
            self.assertTrue(result.evening_report)
            self.assertTrue(result.stock_pool_structure_summary)
            self.assertIn(
                "\u9996\u4e2a\u57fa\u7ebf",
                result.stock_pool_comparison_highlight_summary,
            )
            self.assertIn(
                "\u7b49\u5f85\u9996\u4e2a\u57fa\u7ebf",
                result.stock_pool_comparison_tag_labels,
            )
            self.assertIn("7.", result.morning_report)
            self.assertIn("core", result.evening_report)
        finally:
            shutil.rmtree(temp_dir, ignore_errors=True)

    def test_build_cycle_console_output_can_append_latest_review(self) -> None:
        temp_dir = Path(tempfile.mkdtemp())
        database_path = temp_dir / "monitor.db"
        snapshot_path = temp_dir / "stock_pool_health_snapshot.json"
        try:
            with (
                patch.dict(
                    "os.environ",
                    {
                        "MONITOR_DATABASE_PATH": str(database_path),
                        "MONITOR_STOCK_POOL_HEALTH_SNAPSHOT_PATH": str(snapshot_path),
                        "MONITOR_AUTO_LATEST_REVIEW": "true",
                    },
                    clear=False,
                ),
                patch("app.pipeline.fetch_realtime_quotes", return_value=pd.DataFrame()),
            ):
                config = load_config()
                result = run_monitor_cycle(config)
            output = build_cycle_console_output(config, result)

            self.assertIn("AI 半导体监控", output)
            self.assertIn("焦点：全流程本地监控", output)
            self.assertIn("结果：", output)
            self.assertIn("Pool drift: awaiting first baseline.", output)
            self.assertLess(output.find("结果："), output.find("焦点：全流程本地监控"))
            self.assertIn("Aligned chain:", output)
            self.assertIn("市场焦点快照", output)
            self.assertIn(
                "行情来源：demo-fallback (built-in demo data)",
                output,
            )
            self.assertNotIn("Environment:", output)
            self.assertNotIn("Database:", output)
            self.assertIn("最新数据库复盘", output)
            self.assertIn("监控池观察", output)
            self.assertIn("阶段链条焦点：", output)
            self.assertIn("股票池覆盖：", output)
            self.assertIn("Intraday Alert Digest", output)
            self.assertIn("Close Alert Digest", output)

            shutil.rmtree(temp_dir, ignore_errors=True)
        finally:
            shutil.rmtree(temp_dir, ignore_errors=True)

