    def test_sort_alerts_for_detailed_view_prioritizes_stage_relevant_high_value(self) -> None:
        sorted_alerts = _sort_alerts_for_detailed_view(
            [
                {
                    "alert_type": "volume_spike",
                    "level": "orange",
                    "direction": "Materials",
                    "message": "Materials chain volume is rising",
                },
                {
                    "alert_type": "news_flash",
                    "level": "orange",
                    "direction": "Equipment",
                    "message": "Equipment export restriction risk is rising",
                },
                {
                    "alert_type": "sector_move",
                    "level": "orange",
                    "direction": "Equipment",
                    "message": "Equipment chain is active",
                },
            ],
            intent_strategy={"preferred_chain_groups": ["Equipment"]},
        )

        self.assertEqual("sector_move", sorted_alerts[0]["alert_type"])
        self.assertEqual("news_flash", sorted_alerts[1]["alert_type"])
        self.assertEqual("volume_spike", sorted_alerts[2]["alert_type"])

