    def test_resolve_detailed_alert_field_specs_can_switch_by_priority(self) -> None:
        high_value_fields = _resolve_detailed_alert_field_specs(
            {"alert_type": "news_flash"}
        )
        watch_fields = _resolve_detailed_alert_field_specs(
            {"alert_type": "volume_spike"}
        )

        self.assertEqual("related_stocks", high_value_fields[2]["key"])
        self.assertEqual("message", watch_fields[2]["key"])
        self.assertFalse(
            any(field["key"] == "related_stocks" for field in watch_fields)
        )

